export function parseCoordinates(value){if(!value?.trim())return null;const parts=value.trim().split(/[,;\s]+/).map(Number);return parts.length===2&&parts.every(Number.isFinite)&&Math.abs(parts[0])<=90&&Math.abs(parts[1])<=180?parts:null}
let observer;
export function attachCoordinates(){observer?.disconnect();const root=document.querySelector('#stops');if(!root)return;function attach(){for(const row of root.children){if(row.querySelector('.coordinate-field'))continue;const label=document.createElement('label');label.className='coordinate-field';label.style.gridColumn='1/-1';label.textContent='Координаты точки (необязательно): широта, долгота';const input=document.createElement('input');input.placeholder='53.9006, 27.5590';input.value=row.dataset.coords||'';input.maxLength=60;input.oninput=()=>{const p=parseCoordinates(input.value);input.setCustomValidity(input.value.trim()&&!p?'Укажите широту от −90 до 90 и долготу от −180 до 180 через запятую.':'');if(p)row.dataset.coords=p.join(', ');else delete row.dataset.coords};label.append(input);row.append(label)}}observer=new MutationObserver(attach);observer.observe(root,{childList:true});attach()}
export function showRouteMap(route,modal,esc){const points=route.legs.map(l=>({name:l.to,p:parseCoordinates(l.coords)})).filter(x=>x.p);if(!points.length){modal('Точки на карте','<p>Откройте «Изменить» у маршрута и укажите координаты нужных остановок, например 53.9006, 27.5590.</p><div class="notice">Координаты можно скопировать из любой карты. Порядок: широта, долгота. Они сохранятся на устройстве.</div>');return}const lats=points.map(x=>x.p[0]),lons=points.map(x=>x.p[1]),minLat=Math.min(...lats)-.12,maxLat=Math.max(...lats)+.12,minLon=Math.min(...lons)-.18,maxLon=Math.max(...lons)+.18;const xy=p=>[30+(p[1]-minLon)/(maxLon-minLon)*400,210-(p[0]-minLat)/(maxLat-minLat)*180];
modal('Точки маршрута',`<div class="notice" style="margin-top:0">Схема координат · север ↑<br>Это расположение точек, не дорожная карта. Расстояния по дорогам вводятся вручную.</div><svg viewBox="0 0 460 240" role="img" aria-label="Схема расположения остановок" style="width:100%;background:#080b07;border:1px solid #30392a;border-radius:10px"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#20281c"/></pattern></defs><rect width="460" height="240" fill="url(#grid)"/><polyline points="${points.map(x=>xy(x.p).join(',')).join(' ')}" fill="none" stroke="#687d50" stroke-dasharray="5 5"/>${points.map((x,i)=>{const[a,b]=xy(x.p);return `<circle cx="${a}" cy="${b}" r="12" fill="#c5f277"/><text x="${a}" y="${b+4}" text-anchor="middle" font-size="12" fill="#111">${i+1}</text>`}).join('')}</svg><div>${points.map((x,i)=>`<div class="split"><strong>${i+1}. ${esc(x.name)}</strong><span>${esc(x.p.join(', '))}</span></div>`).join('')}</div><div class="card-actions">${points.map((x,i)=>`<button type="button" class="quiet" data-map-point="${i}">Карта: ${esc(x.name)} ↗</button>`).join('')}</div><p class="hint">Подробная карта загружается из OpenStreetMap при нажатии. Нужен интернет; выбранные координаты передаются OpenStreetMap.</p><div id="map-frame"></div>`);
document.querySelectorAll('[data-map-point]').forEach(b=>b.onclick=()=>{const x=points[Number(b.dataset.mapPoint)],lat=x.p[0],lon=x.p[1],box=[lon-.025,Math.max(-90,lat-.018),lon+.025,Math.min(90,lat+.018)].join(',');const iframe=document.createElement('iframe');iframe.title='OpenStreetMap: '+x.name;iframe.src='https://www.openstreetmap.org/export/embed.html?bbox='+encodeURIComponent(box)+'&layer=mapnik&marker='+encodeURIComponent(lat+','+lon);iframe.style='width:100%;height:300px;border:1px solid #333;border-radius:10px;margin-top:16px';iframe.referrerPolicy='no-referrer';document.querySelector('#map-frame').replaceChildren(iframe)})}
